CREATE OR REPLACE VIEW "observer"."agents" AS (select "agents"."id", "agents"."project_id", "agents"."name", "agents"."client", "agents"."capabilities", "agents"."last_seen_at", "agents"."created_at", "project_tokens"."id" as "connection_id", "project_tokens"."label" as "connection_label", "project_tokens"."expires_at" as "connection_expires_at", "project_tokens"."revoked_at" as "connection_revoked_at" from "agents" left join "project_tokens" on ("project_tokens"."id" = "agents"."registered_via_token_id" and "project_tokens"."project_id" = "agents"."project_id"));
